-- Rivals Coach — guide de rôle Duelist, guide « Construire et contrer une compo », apprentissage des portraits
--   · guides : rôle Duelist (cinq vidéos), guide général team-comps (cinq vidéos)
--   · compos : plans de jeu, alternatives et « fort contre / faible contre » complétés.
--     ATTENTION : le contenu des six compos d'origine est remplacé. Si tu les as modifiées dans Admin > Compos,
--     reporte tes changements après coup.
--   · quiz : huit questions (rôle Duelist, compos)
--   · learn_fingerprints : enregistre des portraits nommés sans créer de partie (écran « Apprendre les portraits »)
-- À exécuter après 0018_capture_fix_nightcrawler_loki.sql. Ré-exécutable.

-- 1. Guides
insert into public.guides (kind, role, status, content) values ('role', 'Duelist', 'published', $j${"tags": ["Angles décalés", "Choix de cible", "Timing"], "tldr": ["Tes dégâts ne comptent que s'ils **mènent à une élimination** : tirer sur un tank soigné charge les ults d'en face.", "Prends un **angle décalé** : l'ennemi ne doit pas pouvoir te voir en même temps que ton équipe.", "Entre **quand ton équipe se bat**, ressors dès qu'on se retourne sur toi."], "summary": "Faire beaucoup de dégâts ne suffit pas : on peut finir meilleur joueur de l'équipe perdante. Un bon Duelist choisit où il se place, sur qui il tire et à quel moment il entre. La visée vient ensuite.", "difficulty": 2, "patch_note": "Principes valables quelle que soit la saison. Les exemples de héros dépendent de la méta du moment.", "counters": [], "synergies": [], "sections": [{"title": "Ton vrai objectif : des dégâts utiles", "items": ["Des dégâts sur un **tank soigné** ne tuent personne et **chargent les ults** des soutiens adverses.", "Ton travail : **créer un surnombre**. À 6 contre 5, l'ennemi recule et ton équipe prend le terrain.", "Tu crées aussi de l'**espace** : un Duelist qui menace la backline oblige l'ennemi à se retourner, et ton tank respire.", "Sans pression de ta part, les bons adversaires **avancent sur ton équipe**."], "lead": "Tous les dégâts ne se valent pas. Ceux qui comptent font tomber quelqu'un ou forcent un cooldown.", "kind": "tips"}, {"title": "Connaître ton type de Duelist", "items": ["**Dégâts constants** (The Punisher, Hela, Winter Soldier) : tu tires presque sans arrêt. Reste proche du fight, sur un angle court.", "**Burst** (Black Panther, Spider-Man, Iron Fist) : presque tous tes dégâts passent par tes capacités. Tu entres, tu frappes, tu ressors, puis tu attends tes cooldowns.", "**Brawl** (Winter Soldier, Wolverine, Mister Fantastic) : tu gagnes au contact, sur la ligne de front adverse.", "**Dive** (Daredevil, Spider-Man, Black Panther) : tu ne perds pas de temps sur les tanks, tu prépares une entrée sur une cible fragile.", "**Poke** (Hela, Hawkeye, Moon Knight) : tu uses de loin. Un bouclier te bloque : change d'angle pour le contourner.", "Accorde-toi à ton équipe : si ton héros ne suit pas ce qu'elle fait, **change de héros** plutôt que de jouer à part."], "lead": "Les principes sont les mêmes pour tous, mais on ne les applique pas pareil avec The Punisher et avec Black Panther."}, {"title": "Prendre un angle décalé", "items": ["Bon angle : l'ennemi **ne peut pas avoir ton équipe et toi sur le même écran**.", "S'il t'ignore, tu tires librement. S'il se retourne, **ton équipe avance**. Dans les deux cas tu gagnes.", "Condition 1 : **ton équipe se bat déjà**. Seul face à six regards, tu meurs avant le fight.", "Condition 2 : **ne reste pas**. Dès qu'on te tire dessus, mets-toi à couvert, attends quelques secondes, reviens. Sois le moustique qu'on n'arrive pas à écraser.", "Ta distance dépend de ta **mobilité** : Hela ne s'éloigne pas plus loin qu'un envol de son équipe ou d'un pack de soin. Psylocke ou Black Panther vont beaucoup plus loin.", "Un bouclier d'Invisible Woman, un drone d'Ultron ou un flocon de Luna Snow sur toi te permettent d'aller **un cran plus loin**.", "Avec des dégâts constants, prends des angles **courts** : un grand détour, ce sont des secondes sans tirer."], "lead": "Un joueur ne regarde que dans une direction. Si tu tires d'ailleurs que ton équipe, il doit choisir qui regarder.", "diagram": "angle"}, {"title": "Flanquer au bon moment", "items": ["**Trop tôt**, tout le monde se retourne sur toi. **Trop tard**, tes éliminations ne changent plus rien. Entre quand le fight commence.", "Pendant ton détour, **ton équipe joue à 5 contre 6** : elle prend plus de dégâts et demande plus de soins.", "Tu ne seras **pas soigné** là-bas : repère un pack de soin et garde ta capacité de fuite.", "Un ennemi que tu viens de tuer **revient par le chemin le plus court** depuis sa base : ne reste pas sur sa route.", "Si le fight n'est pas gagné après tes capacités, **ressors** et prépare le suivant.", "Essaie une fois. Si ta backline meurt pendant ton détour et que tu ne tues personne en arrivant, **reviens jouer avec ton équipe**."], "lead": "Un flank est un angle plus profond, dans le dos de l'ennemi. Il rapporte plus et pardonne moins.", "diagram": "flank"}, {"title": "Choisir ta cible", "items": ["Cherche le joueur **isolé** : celui qui ne recevra pas de soins tombe, quel que soit son rôle.", "Tire sur la cible que **tes alliés tirent déjà** : deux joueurs sur la même cible dépassent les soins qu'elle reçoit.", "Soutien **facile d'accès**, à quelques mètres derrière son tank : c'est lui. Sinon, le **Duelist adverse** est souvent la meilleure cible : il fait le plus de dégâts et reçoit le moins de soins.", "Deux soutiens ? Vise **celui du fond** : celui de devant ne se retourne pas pour le soigner.", "Un **tank** se tue quand il a fait une erreur : attrapé, coupé de ses soins, ou ses soutiens occupés par un dive.", "Dès qu'une meilleure cible se montre, **quitte le tank**. C'est la cible par défaut, pas la bonne cible.", "Regarde où ta cible **recule** : vers un terrain vide, finis-la. Vers sa base ou son équipe, laisse-la partir."], "lead": "« Toujours les soutiens » est une règle fausse. La bonne cible est celle qui peut mourir maintenant."}, {"title": "Protéger tes soutiens", "items": ["Garde un œil sur **leur position et leur vie**, et sur les chemins de flank qui mènent à eux.", "Un diver arrive : **retourne-toi et tue-le vite**. Tu reprends ta pression ensuite, à 6 contre 5.", "Avant de partir en flank, vérifie deux choses : **y a-t-il un flanker en face**, et un allié est-il déjà parti sur le côté ?", "Trois soutiens solides ensemble se défendent seuls. Deux soutiens fragiles face à un Spider-Man, non.", "Sans soutiens, **personne ne te soigne** au retour de ton dive : les protéger, c'est te protéger."], "lead": "Le Duelist d'en face veut tes soutiens, et ton tank est occupé devant. Quand tu ne plonges pas, c'est à toi.", "diagram": "peel"}, {"title": "Ne pas donner ta vie", "items": ["**Ne plonge pas seul sur six joueurs** : entre le premier si tu veux, mais avec ton équipe juste derrière.", "Seule exception : une **ult** faite pour toucher plusieurs cibles, lancée d'un flank pendant que ton équipe engage.", "**Ne poursuis pas** une cible basse jusque dans son équipe : c'est souvent un appât.", "Deux ennemis bas en vie et regroupés : là, **vas-y**. Hésiter les laisse se faire soigner.", "Attire un poursuivant **loin de son équipe**, gagne le duel, puis repars.", "Tu rates un tir, tu meurs : **passe au fight suivant**. S'énerver contre soi ou contre son équipe fait jouer moins bien."], "lead": "Chaque mort fait jouer un fight à 5 contre 6. Un bon Duelist sait aussi quand ne pas y aller."}, {"title": "Scouter et annoncer", "items": ["Annonce le **soutien mal placé** ou la cible isolée avant le fight.", "Annonce le **flanker adverse** qui part vers tes soutiens, et va à sa rencontre avec ton équipe.", "Quand tu meurs, dis **qui t'a tué et d'où** : « Hela dans le couloir de droite ».", "Un adversaire qui ne tire plus depuis dix secondes **n'est pas parti** : il contourne ou prépare son ult. Dis-le.", "Exercice : en partie rapide, demande-toi sans arrêt **où sont tes cinq alliés, puis les six ennemis**."], "lead": "Tu vois ce que ton équipe ne voit pas. Un mot ou un ping suffit."}, {"title": "Exercice : rester invisible", "items": ["Attends que **les deux équipes se battent**.", "Place-toi sur un angle ou dans le dos de l'ennemi, **sans tirer**.", "**Compte les secondes** avant qu'un ennemi te remarque.", "Repéré tout de suite : angle trop visible, fight pas assez engagé ou mauvais timing. Plusieurs secondes : c'était le bon endroit, et tes tirs auraient surpris tout le monde.", "Refais-le avec **plusieurs héros**, à pied avec The Punisher comme en mobilité avec Spider-Man.", "Pour aller plus loin : regarde des **matchs pro** dans l'onglet Tournois en suivant un seul Duelist. Regarde quand il attend."], "lead": "À faire en partie rapide. C'est le moyen le plus rapide de sentir ce qu'est un bon angle.", "kind": "tips"}, {"title": "Visée et déplacement", "items": ["Vise **la tête** : à haut rang, les tirs au corps ne suffisent plus face à Hela, Hawkeye ou Star-Lord.", "Routine : **100 tirs à la tête par jour** sur les mannequins du stand d'entraînement.", "Héros avec un étourdissement : entraîne **étourdissement puis tir à la tête** sur des bots qui bougent, jusqu'à ce que ce soit automatique.", "**Déplace-toi à l'opposé de ta visée** (viseur vers la gauche, pas vers la droite) : tu es plus dur à toucher et ton viseur reste sur la cible.", "Changer de sens trop vite te ralentit : enchaîne les directions **en cercle** en gardant la touche avancer.", "**15 minutes d'échauffement** avant une partie classée suffisent à la plupart des joueurs."], "lead": "Le placement et le timing font gagner plus de fights que la visée. Mais sans toucher, tu plafonnes.", "kind": "tips"}, {"title": "Erreurs fréquentes", "items": ["Tirer **sur le tank** toute la partie alors que d'autres cibles se montrent.", "Partir en angle **avant que ton équipe se batte**.", "**Rester** sur ton angle quand on se retourne sur toi.", "**Poursuivre** une cible jusque dans son équipe.", "Flanquer **à chaque fight** pendant que tes soutiens meurent.", "Mourir sans **dire qui t'a tué**."], "kind": "mistakes"}], "sources": [{"title": "How To Get So Good At DPS It Feels Like Smurfing", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=EZ-flTeufqw"}, {"title": "How To Get So Good At Duelist It Feels Like Cheating", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=0WpZvJ8lrmU"}, {"title": "The ABSOLUTE BEST Way to Dominate Marvel Rivals with DPS Mastery", "author": "Duck Films", "url": "https://www.youtube.com/watch?v=iQCuN3nn8vI"}, {"title": "The Ultimate Guide to Duelist Mastery in Marvel Rivals", "author": "Duck Films", "url": "https://www.youtube.com/watch?v=uOs62kL9XgM"}, {"title": "Meilleur tuto pour carry vos ranked en Duelliste", "author": "Iker", "url": "https://www.youtube.com/watch?v=PR1pWEnTKNg"}]}$j$::jsonb)
on conflict (role) where kind = 'role' do update set status = 'published', content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, slug, status, content) values ('general', 'team-comps', 'published', $j${"title": "Construire et contrer une compo", "summary": "Une compo, c'est une façon commune de se battre. Trois styles se contrent en boucle, et ce sont les tanks qui décident lequel vous jouez. Ce guide explique comment reconnaître le style d'en face, quoi choisir pour compléter ton équipe et quoi changer quand ça ne marche pas.", "tldr": ["Le **brawl** bat le **dive**, le dive bat le **poke**, le poke bat le brawl.", "Regarde **les tanks** : ils fixent le style, les autres complètent.", "**Complète ce que fait ton équipe** au lieu de prendre ton héros de confort.", "Quand une faiblesse apparaît, **change un héros**, pas tout le plan."], "difficulty": 0, "tags": ["Fondamentaux", "Sélection des héros", "Counters"], "counters": [], "synergies": [], "combos": [], "sections": [{"title": "Les trois styles", "items": ["**Brawl** : on avance groupés et on gagne au contact. Il échange de la vie contre du terrain et demande beaucoup de soins.", "**Dive** : plusieurs joueurs sautent sur la même cible au même moment, la tuent, ressortent.", "**Poke** : on use l'adversaire de loin, avant le contact. C'est le style qui demande le moins de coordination.", "Le **brawl bat le dive** : les divers plongent au milieu d'une équipe groupée.", "Le **dive bat le poke** : les tireurs sont espacés et fragiles au contact.", "Le **poke bat le brawl** : il faut traverser sa zone de tir pour l'atteindre."], "lead": "Presque toutes les compos sont un mélange de trois façons de se battre."}, {"title": "Les tanks décident du style", "items": ["**Poke** : Magneto.", "**Brawl** : The Thing, Emma Frost, Groot.", "**Dive** : Venom, Captain America, Hulk.", "**Entre deux styles** : Thor (brawl ou dive), Doctor Strange (les trois), Peni Parker (généraliste).", "En dive, un **second tank qui ne plonge pas** sert de filet de sécurité à la backline."], "lead": "Avant de choisir ton héros, regarde quels Vanguards ton équipe a pris.", "diagram": "space"}, {"title": "Construire en quatre étapes", "items": ["**Annonce ton héros** dès l'écran de sélection.", "**Regarde les tanks** : ils donnent le style.", "**Comble ce qui manque** : un second tank, un second soutien, des dégâts capables de finir une cible.", "**Change** quand une faiblesse apparaît en cours de partie.", "Renforce ce que ton équipe fait déjà : un héros de confort **qui ne suit pas le plan** affaiblit tout le monde.", "Les héros **hybrides** (Iron Fist, Elsa Bloodstone, Phoenix, Winter Soldier) s'adaptent à plusieurs styles : bons choix quand le plan n'est pas clair."], "lead": "L'ordre compte : on choisit en fonction de ce qui est déjà pris, pas avant."}, {"title": "Les soutiens qui vont avec", "items": ["**Dive** : Jeff, Rocket Raccoon, White Fox. Autonomes, ils suivent le dive ou tiennent un angle seuls.", "**Brawl** : Cloak & Dagger, Invisible Woman. Leurs soins couvrent un groupe serré.", "**Poke** : Mantis, Loki, Luna Snow. Soins et dégâts à distance.", "Trop de soigneurs purs avec **un seul tank** : les ults se chargent lentement et personne ne finit les cibles."], "lead": "Un soutien qui ne peut pas suivre son équipe ne soigne personne."}, {"title": "La carte compte", "items": ["**Couloirs étroits** et points fermés : avantage au brawl.", "**Longues lignes de vue** et hauteurs : avantage au poke.", "**Chemins de contournement** nombreux : avantage au dive.", "Une même carte change d'un point à l'autre : adapte un héros plutôt que de subir."], "lead": "Le terrain favorise un style avant même le premier fight.", "diagram": "choke"}, {"title": "Les répartitions de rôles", "items": ["**2-2-2** : équilibrée, sans faiblesse évidente.", "**Triple Vanguard** : énormément de présence. Elle bat le triple Strategist. Réponse : des Duelists à gros dégâts et des tueurs de tanks (Storm, Iron Fist, Wolverine, Winter Soldier), tous sur la même cible.", "**Triple Strategist** : fights très longs, ults défensives à la chaîne. Elle bat le triple Duelist en survivant au burst. Réponse : le triple Vanguard.", "**Triple Duelist** : beaucoup de dégâts, peu de protection. Elle bat le triple Vanguard si tout le monde tire sur la même cible."], "lead": "Le 2-2-2 est l'équilibre par défaut. Les autres formes ont chacune une force et une réponse."}, {"title": "Compos spéciales", "items": ["**Bunker** (2-1-3 ou 3-0-3) : on s'installe sur l'objectif et on ne bouge plus. Réponse : du burst de zone (The Punisher, Storm, Moon Knight).", "**Rush** (1-3-2) : un seul tank et trois Duelists qui foncent ensemble pour gagner vite.", "**Kidnapping** : Angela ou Thor emportent un ennemi loin de son équipe, puis le fight se joue en surnombre. Réponse : rester groupés et garder un contrôle pour celui qui charge."], "lead": "Trois plans que tu croiseras de temps en temps, avec ce qui les met en échec."}, {"title": "Répondre au style d'en face", "items": ["Face au **dive** : resserrez-vous, jouez près des soutiens et gardez un contrôle pour le premier diver. Si ça continue, passez sur l'anti-dive.", "Face au **brawl** : ne les laissez pas arriver au contact. Tirez pendant qu'ils traversent, **cédez du terrain** quand ils entrent, reprenez-le ensuite.", "Face au **poke** : ne restez pas dans leur ligne de tir. Passez par les couverts ou **plongez à plusieurs** sur leurs tireurs.", "En dive : **faites sortir les cooldowns défensifs** avant de plonger. Gagnez vite ou ressortez : un dive ne protège personne.", "En poke : vous gagnez **avant le fight**. Si le brawl entre, reculez ensemble.", "En brawl : approchez **par les couverts** pour ne pas perdre votre vie en chemin."], "lead": "Reconnaître le style adverse, c'est déjà savoir quoi faire.", "kind": "tips", "diagram": "peel"}, {"title": "Bans et changements", "items": ["Bannis le héros qui **protège l'ennemi contre ta compo**, pas celui que ta compo bat déjà.", "Un seul changement suffit souvent : le héros qui **couvre la faiblesse** apparue."]}, {"title": "Erreurs fréquentes", "items": ["Prendre son **héros de confort** sans regarder les tanks.", "Mettre **un diver seul** dans une compo poke : il plonge sans personne derrière lui.", "Plonger **un par un**.", "Rester dans la ligne de tir d'un poke **sans avancer ni contourner**.", "Empiler les soigneurs avec **un seul tank**."], "kind": "mistakes"}], "sources": [{"title": "The 6 Types of Team Comps (and their counters) in Marvel Rivals", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=a2H0xQEtliU"}, {"title": "You're Countering Team Comps Completely WRONG!", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=vSbTrs7TrpU"}, {"title": "The Best Marvel Rivals Team Comps EXPLAINED", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=fx1P24Y4W-E"}, {"title": "Marvel Rivals Comps EXPLAINED", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=b7a0faQ0tBg"}, {"title": "The Ultimate Marvel Rivals Composition Guide", "author": "Auteur à préciser", "url": "https://www.youtube.com/watch?v=DnhEMyRZe0g"}]}$j$::jsonb)
on conflict (slug) where kind = 'general' do update set status = 'published', content = public.rc_merge_guide(public.guides.content, excluded.content);

-- 2. Compos
update public.team_comps set content = $c${"name": "Brawl au contact", "style": "brawl", "heroes": [{"job": "Ouvre le combat, prend l'espace et reste au contact des ennemis.", "hero": "the-thing", "role": "Vanguard"}, {"job": "Bouclier pour traverser la zone dangereuse, portail pour revenir vite sur le point.", "hero": "doctor-strange", "role": "Vanguard"}, {"job": "Tape les tanks adverses : plus le combat dure, plus il fait mal.", "hero": "wolverine", "role": "Duelist"}, {"job": "Dégâts constants à courte distance, tourelle pour tenir une entrée.", "hero": "the-punisher", "role": "Duelist"}, {"job": "Soins de groupe constants, ult pour gagner le combat prolongé.", "hero": "luna-snow", "role": "Strategist"}, {"job": "Bonus de dégâts sur les duellistes, soins sur la durée, sommeil sur un diver.", "hero": "mantis", "role": "Strategist"}], "summary": "La compo la plus simple à jouer en groupe : deux tanks qui encaissent, deux duellistes qui tapent au contact, deux heals qui soignent large. Personne ne part seul : la force de la compo, c'est d'être collés.", "tagline": "On avance tous ensemble et on gagne le combat au corps à corps.", "weak_vs": [{"comp": "poke", "note": "Ils vous usent de loin avant le contact : coupez la distance par un mur ou un flank."}, {"comp": "air", "note": "Vos héros de mêlée n'atteignent pas les volants."}, {"comp": "groot-trap", "note": "Une équipe groupée est la cible idéale de l'ult de Groot : écartez-vous quand elle est prête."}], "best_when": ["Les cartes avec des **passages étroits** et des points fermés.", "Ton équipe aime jouer **groupée** et parle peu : il y a peu de timing à caler.", "L'équipe d'en face **dive** sur vos heals : groupés, vous les punissez."], "game_plan": ["Approchez **par les couverts** : chaque point de vie perdu en chemin manque au contact.", "Regroupez-vous **derrière un mur** juste avant la zone de combat.", "Le tank principal annonce le départ, puis **tout le monde avance en même temps**.", "Bouclier levé pour traverser la zone découverte, sans s'arrêter.", "Au contact, **tapez tous la même cible**, en commençant par le plus proche.", "Gardez l'**ult de soin** pour le moment où les ennemis lancent leurs ults."], "strong_vs": [{"comp": "dive", "note": "Groupés, vous attrapez les divers qui arrivent dans votre zone."}], "difficulty": 1, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "thor", "note": "Plus de mobilité pour ramener un tank ennemi dans ta zone.", "replaces": "the-thing"}, {"hero": "emma-frost", "note": "Bouclier solide et forme de diamant pour tenir le point.", "replaces": "doctor-strange"}, {"hero": "magik", "note": "Plus de burst au contact, mais demande des combos.", "replaces": "wolverine"}, {"hero": "adam-warlock", "note": "Sa résurrection de groupe sauve un combat perdu.", "replaces": "mantis"}, {"hero": "groot", "replaces": "doctor-strange", "note": "Ses murs coupent l'équipe adverse en deux au contact."}, {"hero": "cloak-and-dagger", "replaces": "mantis", "note": "Soins de zone : parfaits sur une équipe collée."}, {"hero": "invisible-woman", "replaces": "luna-snow", "note": "Soigne tout le groupe en ligne et repousse ce qui s'approche."}], "failure_signs": ["Vous **perdez de la vie avant même le contact** : l'ennemi vous harcèle de loin.", "Un tank part **seul devant** et meurt avant que les autres arrivent.", "Les heals se retrouvent **loin derrière** et ne soignent plus personne.", "Vos soutiens **n'arrivent plus à suivre** : le brawl échange de la vie contre du terrain, il lui faut beaucoup de soins."]}$c$::jsonb where slug = 'brawl';
update public.team_comps set content = $c${"name": "Plongée coordonnée", "style": "dive", "heroes": [{"job": "Dive le premier sur la backline et encaisse grâce à sa vie bonus.", "hero": "venom", "role": "Vanguard"}, {"job": "Suit Venom, protège les divers et relance la pression.", "hero": "captain-america", "role": "Vanguard"}, {"job": "Élimine la cible marquée par le dive, puis ressort avec ses dashes.", "hero": "black-panther", "role": "Duelist"}, {"job": "Arrive par derrière, achève les cibles basses, repart invisible.", "hero": "psylocke", "role": "Duelist"}, {"job": "Suit l'équipe avec son jetpack, balise de résurrection pour les dives ratés.", "hero": "rocket-raccoon", "role": "Strategist"}, {"job": "Vole avec les divers et les soigne là où les autres heals ne vont pas.", "hero": "ultron", "role": "Strategist"}], "summary": "Une compo très mobile qui gagne en éliminant un heal ou un tireur avant que le combat commence vraiment. Elle demande de la communication : un dive à deux réussit, un dive en solo meurt.", "tagline": "Tout le monde saute sur la même cible au même moment, puis ressort.", "weak_vs": [{"comp": "brawl", "note": "Une équipe collée vous attend et vous écrase."}, {"comp": "anti-dive", "note": "Elle est construite exprès pour vous punir."}], "best_when": ["Les cartes **ouvertes avec de la hauteur** et plusieurs chemins.", "L'équipe d'en face a des **tireurs fixes** (snipers, harceleurs à distance).", "Vous jouez **en vocal** : le moment du dive doit être annoncé."], "game_plan": ["**Faites sortir les cooldowns défensifs** avant de plonger : un dive sur une cible protégée échoue.", "Choisissez **une seule cible** avant le combat, idéalement un heal isolé.", "Annoncez le compte « 3, 2, 1 » et **plongez tous en même temps**.", "Tuez la cible, puis **ressortez tout de suite** vers votre équipe.", "Rechargez vos capacités à l'abri, et recommencez sur la cible suivante.", "Si la cible ne tombe pas vite, **ressortez** : un dive qui s'éternise devient un 