update public.team_comps set content = $c${"name": "Poke à distance", "style": "poke", "heroes": [{"job": "Bouclier frontal pour protéger les tireurs, portail pour reprendre la position.", "hero": "doctor-strange", "role": "Vanguard"}, {"job": "Boucliers et bulles pour que les tireurs survivent aux échanges.", "hero": "magneto", "role": "Vanguard"}, {"job": "Tirs à la tête de loin, élimine tout ce qui sort à découvert.", "hero": "hela", "role": "Duelist"}, {"job": "Flèches à très longue portée sur les cibles qui reculent.", "hero": "hawkeye", "role": "Duelist"}, {"job": "Bouclier sur les alliés et poussée pour éloigner ceux qui s'approchent.", "hero": "invisible-woman", "role": "Strategist"}, {"job": "Soins à distance et résurrection pour retourner un combat.", "hero": "adam-warlock", "role": "Strategist"}], "summary": "Une compo qui gagne les combats avant qu'ils commencent : les tireurs touchent de loin, les tanks protègent avec leurs boucliers, et l'ennemi arrive au contact déjà affaibli. Il faut viser juste et tenir sa position.", "tagline": "On use l'adversaire de loin, derrière les boucliers, avant tout contact.", "weak_vs": [{"comp": "dive", "note": "Les divers arrivent sur vos tireurs sans passer par vos boucliers."}], "best_when": ["Les cartes avec de **longues lignes de vue** et des positions en hauteur.", "Vos tireurs **visent bien** : la compo dépend de leurs dégâts.", "L'équipe d'en face **avance lentement** et doit traverser une zone découverte."], "game_plan": ["Prenez une **position avec une longue ligne de vue**, boucliers devant.", "Tirez **avant le combat** : chaque dégât compte quand ils traversent la zone.", "Concentrez le feu sur le **tank** pour casser leur avancée, puis les fragiles.", "Si quelqu'un dive, **reculez ensemble** et tapez-le tous.", "Quand un brawl entre dans votre zone, **cédez le terrain ensemble**, puis reprenez-le une fois leurs capacités utilisées.", "Un tireur prend un **angle décalé** : un bouclier ne protège que d'un côté