update public.team_comps set content = $c${"name": "Anti-dive", "style": "peel", "heroes": [{"job": "Murs pour couper les chemins d'entrée et isoler les divers.", "hero": "groot", "role": "Vanguard"}, {"job": "Toiles et mines autour des heals, nid d'araignées pour tenir la zone.", "hero": "peni-parker", "role": "Vanguard"}, {"job": "Tourelles près des heals : elles tapent tout ce qui dive.", "hero": "namor", "role": "Duelist"}, {"job": "Dégâts constants pour finir les divers coincés.", "hero": "the-punisher", "role": "Duelist"}, {"job": "Soins de groupe, et une boule de neige qui arrête un diver.", "hero": "luna-snow", "role": "Strategist"}, {"job": "Poussée pour renvoyer un diver, bouclier sur l'allié ciblé.", "hero": "invisible-woman", "role": "Strategist"}], "summary": "La réponse quand l'équipe d'en face dive sans arrêt sur vos heals. Murs, toiles, tourelles et poussées : chaque diver qui arrive est ralenti, isolé puis éliminé à plusieurs.", "tagline": "On protège les heals et on punit chaque diver.", "weak_vs": [{"comp": "poke", "note": "Vos outils de protection ne servent à rien contre des tirs de loin."}], "best_when": ["L'équipe d'en face joue **plusieurs divers** (Venom, Spider-Man, Black Panther, Psylocke…).", "Vos heals **meurent en premier** à chaque combat.", "Les points avec **peu d'entrées** : les murs et les mines les bloquent facilement."], "game_plan": ["Posez tourelles, mines et toiles **autour des heals**, pas devant.", "Dès qu'un diver arrive, **tout le monde se retourne** sur lui.", "Coupez sa sortie avec un mur ou un étourdissement, puis **finissez-le à plusieurs**.", "Une fois le diver mort, **reprenez l'espace** devant : c'est du 6 contre 5.", "Le second tank **reste près des soutiens** : c'est le filet de sécurité."], "strong_vs": [{"comp": "dive", "note": "Chaque diver est attendu et puni."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "emma-frost", "note": "Son étranglement arrête un diver net.", "replaces": "groot"}, {"hero": "squirrel-girl", "note": "Le gland étourdissant immobilise les divers, même en ult.", "replaces": "the-punisher"}, {"hero": "mantis", "note": "Le sommeil endort un diver au bon moment.", "replaces": "invisible-woman"}, {"hero": "rocket-raccoon", "note": "Sa balise de résurrection rattrape un dive réussi.", "replaces": "luna-snow"}], "failure_signs": ["L'ennemi **ne dive plus** et vous harcèle de loin : passez sur une autre compo.", "Vos tourelles et mines sont **posées trop loin** des heals.", "Tout le monde **court après un diver** et abandonne le point."]}$c$::jsonb where slug = 'anti-dive';
update public.team_comps set content = $c${"name": "Piège de Groot", "style": "ultcombo", "heroes": [{"job": "Lance l'ult qui regroupe les ennemis, et coupe le terrain avec ses murs.", "hero": "groot", "role": "Vanguard"}, {"job": "Tank principal : tient le front pendant que Groot prépare son ult.", "hero": "emma-frost", "role": "Vanguard"}, {"job": "Ult sur le groupe retenu par Groot : énormes dégâts de zone.", "hero": "moon-knight", "role": "Duelist"}, {"job": "Ult en combo avec Groot, et solide au front le reste du temps.", "hero": "winter-soldier", "role": "Duelist"}, {"job": "Voile pour que ton équipe frappe à travers le combo.", "hero": "cloak-and-dagger", "role": "Strategist"}, {"job": "Soins de groupe, et ult pour survivre au combo adverse.", "hero": "luna-snow", "role": "Strategist"}], "summary": "Une compo construite autour d'un combo d'ults : Groot attire et retient les ennemis au même endroit, puis Moon Knight et Winter Soldier les éliminent en groupe. Le reste du temps, elle joue comme un brawl solide.", "tagline": "L'ult de Groot regroupe les ennemis, les autres ults finissent le travail.", "weak_vs": [{"comp": "dive", "note": "Des divers éparpillés évitent le piège."}], "best_when": ["Les **points fermés** où les ennemis restent groupés.", "Vous avez **les ults chargées en même temps** : comptez-les avant le combat.", "L'équipe d'en face joue **un seul heal avec une ult de soin** : forcez-la d'abord."], "game_plan": ["Avant le combat, **annoncez qui a son ult** : Groot, Moon Knight, Winter Soldier.", "Jouez un brawl classique jusqu'à ce que les ennemis **se regroupent**.", "Groot lance son ult **sur le groupe**, puis les ults de dégâts suivent immédiatement.", "Si l'ennemi lance une ult de soin, **attendez sa fin** pour relancer le combo."], "strong_vs": [{"comp": "brawl", "note": "Une équipe groupée est le rêve de Groot."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "namor", "note": "Ses tourelles et son ult se combinent bien avec Groot.", "replaces": "moon-knight"}, {"hero": "human-torch", "note": "Zones de feu sur les ennemis regroupés.", "replaces": "winter-soldier"}, {"hero": "angela", "note": "Ses ennemis attachés ne peuvent plus fuir l'ult.", "replaces": "emma-frost"}], "failure_signs": ["Un **Adam Warlock** ressuscite tout le monde après votre combo.", "Le **bouclier de Magneto** bloque le projectile de Groot.", "Vous lancez les ults **les unes après les autres** au lieu d'ensemble."]}$c$::jsonb where slug = 'groot-trap';
update public.team_comps set content = $c${"name": "Pression aérienne", "style": "highground", "heroes": [{"job": "Occupe le front au sol et protège la zone avec son bouclier.", "hero": "doctor-strange", "role": "Vanguard"}, {"job": "Pression au sol : force l'ennemi à regarder devant pendant que les volants frappent.", "hero": "thor", "role": "Vanguard"}, {"job": "Harcèle depuis les airs avec de gros dégâts de zone.", "hero": "iron-man", "role": "Duelist"}, {"job": "Pose des zones de feu depuis le ciel pour couper l'équipe adverse.", "hero": "human-torch", "role": "Duelist"}, {"job": "Vole avec les duellistes et les soigne en hauteur.", "hero": "ultron", "role": "Strategist"}, {"job": "Soins à distance et lien d'âmes pour encaisser les tirs.", "hero": "adam-warlock", "role": "Strategist"}], "summary": "Une compo qui met deux duellistes volants en hauteur : ils touchent tout le monde depuis des angles que l'ennemi ne couvre pas. Elle punit les équipes sans tireurs capables de viser en l'air.", "tagline": "Les duellistes attaquent du ciel, l'équipe adverse doit lever la tête.", "weak_vs": [{"comp": "poke", "note": "Des tireurs à distance vous visent sans difficulté."}], "best_when": ["L'équipe d'en face n'a **pas de tireurs précis** (peu de Hela, Hawkeye, Punisher…).", "Les cartes avec **un ciel dégagé** et peu de plafonds.", "Vos volants savent **changer d'angle** plutôt que rester immobiles."], "game_plan": ["Les tanks occupent l'avant **au sol** pour attirer l'attention.", "Les volants montent **sur deux angles différents** : l'ennemi ne peut pas regarder les deux.", "Visez d'abord les **tireurs capables de vous toucher** en l'air.", "Redescendez derrière un mur quand vous êtes bas en vie : **pas de soin en plein ciel**."], "strong_vs": [{"comp": "brawl", "note": "Une équipe de mêlée ne peut pas vous atteindre en l'air."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "storm", "note": "Volante aussi, avec des auras pour l'équipe.", "replaces": "human-torch"}, {"hero": "phoenix", "note": "Mobile en hauteur, gros dégâts de zone.", "replaces": "iron-man"}, {"hero": "magneto", "note": "Plus solide, et ses bulles protègent les volants.", "replaces": "thor"}], "failure_signs": ["Vos volants **tombent dès qu'ils décollent** : l'ennemi a des tireurs précis.", "Les tanks au sol **meurent seuls** parce que les volants sont trop loin.", "Vos heals **ne voient plus** les volants et ne les soignent pas."]}$c$::jsonb where slug = 'air';

-- 3. Quiz (la bonne réponse est rangée en premier, l'app mélange les options)
insert into public.quiz_questions (key, hero_id, map_id, guide_slug, topic, prompt, options, answer, explain, section) values
('role-duelist-1', null, null, 'duelist', 'Placement', 'Tu joues Duelist. Qu''est-ce qu''un bon angle décalé ?', '["Un endroit où l''ennemi ne peut pas me voir en même temps que mon équipe", "L''endroit le plus loin possible de mon équipe", "Juste derrière mon tank, dans son axe", "Toujours une hauteur, quelle que soit la carte"]'::jsonb, 0, 'L''ennemi doit choisir : te regarder ou regarder ton équipe. S''il t''ignore, tu tires librement ; s''il se retourne, ton équipe avance.', 'Prendre un angle décalé'),
('role-duelist-2', null, null, 'duelist', 'Timing', 'Quand faut-il entrer depuis un flank ?', '["Quand mon équipe a commencé à se battre", "Le plus tôt possible, avant tout le monde", "Une fois le fight terminé, pour finir les fuyards", "Dès que mes capacités sont prêtes, peu importe le reste"]'::jsonb, 0, 'Trop tôt, tout le monde se retourne sur toi. Trop tard, tes éliminations ne changent plus rien. Pendant ton détour, ton équipe joue à 5 contre 6 : ne le fais pas durer.', 'Flanquer au bon moment'),
('role-duelist-3', null, null, 'duelist', 'Choix de cible', 'Sur qui un Duelist doit-il tirer en priorité ?', '["Le joueur isolé ou déjà visé par mes alliés, quel que soit son rôle", "Toujours le tank, c''est la cible la plus facile", "Toujours un soutien, même s''il est hors d''atteinte", "Celui qui a le plus de vie"]'::jsonb, 0, 'La bonne cible est celle qui peut mourir maintenant. Des dégâts sur un tank soigné ne tuent personne et chargent les ults des soutiens adverses.', 'Choisir ta cible'),
('role-duelist-4', null, null, 'duelist', 'Mise en situation', 'Tu pars en flank et tes soutiens meurent pendant ton détour, deux fights de suite. Que faire ?', '["Revenir jouer avec mon équipe et protéger mes soutiens", "Flanquer plus profond pour tuer plus vite", "Demander à mes soutiens de mieux se placer", "Continuer : c''est au tank de les protéger"]'::jsonb, 0, 'Le flank n''est pas une obligation. S''il y a un flanker en face et que personne ne garde tes soutiens, c''est à toi de le faire : sans eux, personne ne te soigne non plus.', 'Protéger tes soutiens'),
('team-comps-1', null, null, 'team-comps', 'Styles', 'L''équipe d''en face joue poke, avec des tireurs espacés. Quel style la contre ?', '["Le dive", "Le brawl", "Un autre poke", "Aucun, il faut subir"]'::jsonb, 0, 'Le dive bat le poke : les tireurs sont espacés et fragiles au contact. Le poke bat le brawl, et le brawl bat le dive.', 'Les trois styles'),
('team-comps-2', null, null, 'team-comps', 'Sélection des héros', 'Que regarder en premier pour savoir quel style joue ton équipe ?', '["Les Vanguards choisis", "Le héros du meilleur joueur", "Le nombre de Duelists", "Les ults disponibles"]'::jsonb, 0, 'Les tanks décident du style : Magneto pour le poke, The Thing, Emma Frost ou Groot pour le brawl, Venom, Captain America ou Hulk pour le dive. Les autres complètent.', 'Les tanks décident du style'),
('team-comps-3', null, null, 'team-comps', 'Mise en situation', 'Un brawl entre dans la zone de tir de ta compo poke. Que fait ton équipe ?', '["Elle recule ensemble, puis reprend le terrain", "Elle tient la position coûte que coûte", "Chacun part de son côté", "Elle fonce au contact"]'::jsonb, 0, 'Le poke gagne avant le fight. Quand le brawl arrive au contact, on cède le terrain ensemble et on le reprend une fois leurs capacités utilisées.', 'Répondre au style d''en face'),
('team-comps-4', null, null, 'team-comps', 'Répartition', 'L''ennemi joue trois Vanguards. Quelle est la bonne réponse ?', '["Des Duelists à gros dégâts, tous sur la même cible", "Trois Strategists pour tenir plus longtemps", "Un seul tank et beaucoup de mobilité", "Éviter tous les fights"]'::jsonb, 0, 'Le triple Vanguard bat le triple Strategist. Ce qui le fait tomber : des tueurs de tanks (Storm, Iron Fist, Wolverine, Winter Soldier) et un focus commun.', 'Les répartitions de rôles')
on conflict (key) do update set hero_id = excluded.hero_id, map_id = excluded.map_id, guide_slug = excluded.guide_slug, topic = excluded.topic, prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, section = excluded.section, active = true;

-- 4. Apprentissage des portraits : les empreintes nommées sont partagées par tout le groupe.
--    L'écriture directe dans capture_fingerprints reste fermée ; elle passe par cette fonction.
create or replace function public.learn_fingerprints(p jsonb)
returns int language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  f jsonb;
  n int := 0;
begin
  if v_uid is null then
    raise exception 'Connexion requise';
  end if;
  if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p) > 300 then
    raise exception 'Liste d''empreintes invalide';
  end if;
  for f in select * from jsonb_array_elements(p) loop
    if (f ->> 'kind') in ('banner', 'avatar')
       and char_length(f ->> 'fp') between 100 and 800
       and (f ->> 'fp') ~ '^[A-Za-z0-9+/=]+$'
       and (f ->> 'hero_id') ~ '^[0-9]{1,9}$'
       and exists (select 1 from heroes where id = (f ->> 'hero_id')::int) then
      insert into capture_fingerprints (kind, hero_id, fp, created_by)
      values (f ->> 'kind', (f ->> 'hero_id')::int, f ->> 'fp', v_uid)
      on conflict (kind, fp) do update set hero_id = excluded.hero_id, created_by = excluded.created_by;
      n := n + 1;
    end if;
  end loop;
  return n;
end $$;
revoke execute on function public.learn_fingerprints(jsonb) from public, anon;
grant execute on function public.learn_fingerprints(jsonb) to authenticated;
